// Opt-in synthetic stress cases, never imported by product code or forwarded upstream.
export function r16Fixture({owner,fid,date}){
 const assets=['harbor','book','window'].map((id,index)=>({id:'r16-'+id,kind:'image',mime_type:'image/png',origin:'owner_upload',title:['海边的下午 · 隔离样本','读到一半的书 · 隔离样本','窗外的树 · 隔离样本'][index],source_filename:id+'.png',byte_size:136163+index*1024,created_at:date,status:'available',read_state:'readable',readable:true,version:1,asset_revision:1,source_state:'owner_original',source_snapshot:null,metadata:{tags:[]},hidden:false}));
 let notices=[{id:'r16-notice',fluctlight_id:fid,title:'一条很长的通知标题，用于确认窄屏仍然完整可读',body:'这是隔离验收样本。'.repeat(25),preview:'这条通知保留真实长度，用于验证换行、读取状态和返回路径。'.repeat(5),created_at:date,link:'#/c/'+fid+'/life/schedule',read_at:null}];
 const record=(kind,index)=>({kind,ref:kind+'-'+index,occurred_at:new Date(Date.parse(date)-index*86400000).toISOString(),data:{id:kind+'-'+index,fluctlight_id:fid,agent_id:'wake-up',scenario:'wake_up',binding_role:'generic_llm',model_id:'fixture-model',status:index%3===0?'failed':'completed',started_at:new Date(Date.parse(date)-index*86400000).toISOString(),completed_at:new Date(Date.parse(date)-index*86400000+2300).toISOString(),prompt:[{role:'system',content:'# 阅读规则\n保持已经记录的资料。'},{role:'user',content:JSON.stringify({text:'核对这一段真实输入',context:{summary:'前一段经历'}})}],response:index%3===0?null:{text:'**这是已记录的模型正文**\n可以分段阅读。',structured:{summary:'这是独立的结构化结果。'}},summary:'**日常唤醒**：完成资料核对，保留原始记录。',error_code:index%3===0?'provider_request_failed':undefined}});
 return ({path,method,url,json,res})=>{const send=value=>{json(res,value);return true;};
  if(path==='/api/runtime-catalog')return send({agents:['conversation-cognition','conversation-reply','conversation-summary','daily-review','diary-expression','diary-material','goal-evaluation','goal-planner','initialization','media-prompt','media-quality','native-cognition','npc-response','persistent-switch','persona-compilation','reflection','schedule-generation','schedule-replan','studio-assistant','studio-text-preview','takeover-judge','takeover-reply','reply-action-check','visual-identity'].map(name=>({name:'fluctlight-'+name,binding_role:'generic_llm',description:'隔离样本运行场景'})),tools:[]});
  if(path.startsWith('/api/diagnostic-records/')){const parts=path.split('/').filter(Boolean),kind=decodeURIComponent(parts[2]);if(parts.length>3){const ref=decodeURIComponent(parts.slice(3).join('/')),index=Number(ref.split('-').at(-1))||0;return send(record(kind,index));}const start=Number(url.searchParams.get('cursor')?.replace('r16-cursor-','')||0),total=kind==='model-runs'?45:kind==='agent-runs'?3:kind==='lifecycle'?2:0,limit=Math.min(Number(url.searchParams.get('limit')||20),20);return send({items:Array.from({length:Math.max(0,Math.min(limit,total-start))},(_,index)=>record(kind,start+index)),next_cursor:start+limit<total?'r16-cursor-'+(start+limit):'',snapshot:'r16-stable',as_of:date});}
  if(path==='/api/media-library')return send({items:assets,next_cursor:''});
  if(path.startsWith('/api/media/r16-')){res.writeHead(200,{'content-type':'image/svg+xml','cache-control':'no-store'});res.end('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect width="800" height="600" fill="#c7ded5"/><path d="M0 420L180 250L400 400L600 200L800 380V600H0Z" fill="#6b9688"/><circle cx="650" cy="100" r="48" fill="#f0e2b4"/></svg>');return true;}
  if(path.startsWith('/api/media-library/')){const id=path.split('/')[3],asset=assets.find(asset=>asset.id===id);if(asset&&path.split('/').length===4)return send(asset);if(path.endsWith('/references'))return send({items:[],next_cursor:''});}
  if(path==='/api/notifications'&&method==='GET')return send({items:notices,next_cursor:'',as_of:date});
  if(path.includes('/notifications/')&&method!=='GET'){notices=notices.map(notice=>({...notice,read_at:date}));return send({});}
  if(path==='/api/notifications/unread-count')return send({count:notices.filter(notice=>!notice.read_at).length});
  return false;
 };
}
